/**
 * Executes code migrations by implementing changes from a migration plan in a phased, verified approach.
 * @category migration
 * @category write
 * @context coding
 */
import { ToolLoopAgent, type LanguageModel } from "ai"
import {
	applyEnvironment,
	type EnvironmentOptions,
	getEnvironmentContext,
} from "@/agents/lib/environment"
import { FULL_BASH_PERMISSIONS } from "@/agents/lib/permissions"
import {
	createContextSummarizer,
	stopOnTextResponse,
} from "@/agents/lib/step-utils"
import { prompt } from "@/prompts/migration-agent"
import { createBashTool } from "@/tools/bash"
import { createEditTool } from "@/tools/edit"
import { globTool } from "@/tools/glob"
import { grepTool } from "@/tools/grep"
import { listTool } from "@/tools/list"
import { readTool } from "@/tools/read"
import { createTodoTools, type TodoStorage } from "@/tools/todo"
import { createWriteTool } from "@/tools/write"

export interface AgentSettings {
	model: LanguageModel
	cwd?: string
	environment?: EnvironmentOptions
	todoStorage?: TodoStorage
}

export async function createAgent({
	model,
	cwd,
	environment,
	todoStorage,
}: AgentSettings) {
	const env = await getEnvironmentContext({ cwd, ...environment })
	const instructions = applyEnvironment(prompt, env)
	const { todoRead, todoWrite } = createTodoTools(todoStorage)

	return new ToolLoopAgent({
		model,
		instructions,
		tools: {
			read: readTool,
			write: createWriteTool(),
			edit: createEditTool(),
			bash: createBashTool(FULL_BASH_PERMISSIONS),
			list: listTool,
			grep: grepTool,
			glob: globTool,
			todoRead,
			todoWrite,
		},
		prepareStep: createContextSummarizer(model),
		providerOptions: {
			openai: {
				reasoningEffort: "medium",
				reasoningSummary: "detailed",
			},
			anthropic: {
				thinking: {
					type: "enabled",
					budgetTokens: 10000,
				},
			},
		},
		stopWhen: stopOnTextResponse,
	})
}

import { execSync } from "child_process"
import { existsSync } from "fs"
import { readdir, readFile, stat } from "fs/promises"
import { homedir } from "os"
import { dirname, join } from "path"

export interface EnvironmentContext {
	workingDirectory: string
	platform: string
	date: string
	isGitRepo: boolean
	fileTree?: string
	customRules?: string[]
}

export interface EnvironmentOptions {
	cwd?: string
	includeFileTree?: boolean
	fileTreeLimit?: number
	includeCustomRules?: boolean
	customRuleFiles?: string[]
}

function detectGitRepo(cwd: string): boolean {
	try {
		execSync("git rev-parse --is-inside-work-tree", { cwd, stdio: "pipe" })
		return true
	} catch {
		return false
	}
}

async function generateFileTree(cwd: string, limit = 200): Promise<string> {
	try {
		const output = execSync(
			"git ls-files --cached --others --exclude-standard",
			{ cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] },
		)
		return output.trim().split("\n").filter(Boolean).slice(0, limit).join("\n")
	} catch {
		const files = await walkDirectory(cwd, limit)
		return files.join("\n")
	}
}

const IGNORE_DIRS = new Set([
	"node_modules",
	".git",
	"dist",
	"build",
	".next",
	"__pycache__",
	".turbo",
	".cache",
	"coverage",
])

async function walkDirectory(
	dir: string,
	limit: number,
	prefix = "",
): Promise<string[]> {
	try {
		const entries = await readdir(dir)
		const filtered = entries.filter(
			(e) => !IGNORE_DIRS.has(e) && !e.startsWith("."),
		)

		const results = await Promise.all(
			filtered.map(async (entry) => {
				const fullPath = join(dir, entry)
				const relativePath = prefix ? `${prefix}/${entry}` : entry

				try {
					const s = await stat(fullPath)
					if (s.isDirectory()) {
						return walkDirectory(fullPath, limit, relativePath)
					}
					return [relativePath]
				} catch {
					return []
				}
			}),
		)

		return results.flat().slice(0, limit)
	} catch {
		return []
	}
}

const DEFAULT_RULE_FILES = ["AGENTS.md", "CLAUDE.md", "CONTEXT.md"]
const GLOBAL_RULE_PATHS = [
	join(homedir(), ".config", "agents", "AGENTS.md"),
	join(homedir(), ".claude", "CLAUDE.md"),
]

async function loadCustomRules(
	cwd: string,
	additionalFiles: string[] = [],
): Promise<string[]> {
	const ruleFiles = [...DEFAULT_RULE_FILES, ...additionalFiles]
	const found = new Set<string>()
	const paths: Array<{ path: string; isGlobal: boolean }> = []

	let dir = cwd
	const root = dirname(dir)
	while (dir !== root) {
		for (const file of ruleFiles) {
			const filePath = join(dir, file)
			if (!found.has(filePath) && existsSync(filePath)) {
				paths.push({ path: filePath, isGlobal: false })
				found.add(filePath)
			}
		}
		dir = dirname(dir)
	}

	for (const filePath of GLOBAL_RULE_PATHS) {
		if (!found.has(filePath) && existsSync(filePath)) {
			paths.push({ path: filePath, isGlobal: true })
			found.add(filePath)
		}
	}

	const results = await Promise.all(
		paths.map(async ({ path, isGlobal }) => {
			try {
				const content = await readFile(path, "utf-8")
				const prefix = isGlobal ? "Global instructions" : "Instructions"
				return `# ${prefix} from ${path}\n\n${content}`
			} catch {
				return null
			}
		}),
	)

	return results.filter((r) => r !== null)
}

/**
 * Gathers rich environment context for the agent's system prompt.
 * Includes working directory, platform, git status, file tree, and custom rules (AGENTS.md, etc.).
 */
export async function getEnvironmentContext(
	options: EnvironmentOptions = {},
): Promise<EnvironmentContext> {
	const {
		cwd = process.cwd(),
		includeFileTree = true,
		fileTreeLimit = 200,
		includeCustomRules = true,
		customRuleFiles = [],
	} = options

	const isGitRepo = detectGitRepo(cwd)

	const [fileTree, customRules] = await Promise.all([
		includeFileTree ? generateFileTree(cwd, fileTreeLimit) : undefined,
		includeCustomRules ? loadCustomRules(cwd, customRuleFiles) : undefined,
	])

	return {
		workingDirectory: cwd,
		platform: process.platform,
		date: new Date().toDateString(),
		isGitRepo,
		fileTree,
		customRules,
	}
}

/**
 * Appends environment context (working directory, platform, file tree,
 * custom rules) to a base prompt string.
 */
export function applyEnvironment(
	basePrompt: string,
	env: EnvironmentContext,
): string {
	const sections: string[] = [basePrompt]

	sections.push(`# Environment

<env>
Working directory: ${env.workingDirectory}
Platform: ${env.platform}
Date: ${env.date}
Git repository: ${env.isGitRepo ? "yes" : "no"}
</env>`)

	if (env.fileTree) {
		sections.push(`# Project Files

<files>
${env.fileTree}
</files>`)
	}

	if (env.customRules && env.customRules.length > 0) {
		sections.push(env.customRules.join("\n\n"))
	}

	return sections.join("\n\n")
}

/**
 * Permission level for a tool operation.
 * - "allow": Auto-approve, no user confirmation needed
 * - "deny": Block the operation entirely
 * - "ask": Require user approval before proceeding
 */
export type Permission = "allow" | "deny" | "ask"

export const FILE_READ_COMMANDS: Record<string, Permission> = {
	"ls*": "allow",
	"pwd*": "allow",
	"cat*": "allow",
	"head*": "allow",
	"tail*": "allow",
	"less*": "allow",
	"more*": "allow",
	"wc*": "allow",
	"file*": "allow",
	"stat*": "allow",
	"du*": "allow",
}

export const SEARCH_COMMANDS: Record<string, Permission> = {
	"grep*": "allow",
	"rg*": "allow",
	"find*": "allow",
	"tree*": "allow",
	"which*": "allow",
	"whereis*": "allow",
}

export const TEXT_PROCESSING_COMMANDS: Record<string, Permission> = {
	"sort*": "allow",
	"uniq*": "allow",
	"cut*": "allow",
	"diff*": "allow",
}

export const GIT_READ_COMMANDS: Record<string, Permission> = {
	"git status*": "allow",
	"git diff*": "allow",
	"git log*": "allow",
	"git show*": "allow",
	"git branch": "allow",
	"git branch -v": "allow",
	"git branch -a": "allow",
	"git remote -v": "allow",
	"git blame*": "allow",
}

/** Dangerous commands that should always be denied */
export const DANGEROUS_COMMANDS: Record<string, Permission> = {
	"rm -rf /*": "deny",
	"rm -rf /": "deny",
	"sudo rm*": "deny",
	"chmod 777*": "deny",
}

/** Full bash access with dangerous command guards. Requires user approval for unknown commands. */
export const FULL_BASH_PERMISSIONS: Record<string, Permission> = {
	...FILE_READ_COMMANDS,
	...SEARCH_COMMANDS,
	...TEXT_PROCESSING_COMMANDS,
	...GIT_READ_COMMANDS,
	...DANGEROUS_COMMANDS,
	"*": "ask",
}

/** Read-only bash access. Denies any command not explicitly allowed. */
export const READONLY_BASH_PERMISSIONS: Record<string, Permission> = {
	...FILE_READ_COMMANDS,
	...SEARCH_COMMANDS,
	...TEXT_PROCESSING_COMMANDS,
	...GIT_READ_COMMANDS,
	"*": "deny",
}

/**
 * Match a value against a wildcard pattern.
 *
 * @param value - The string to test
 * @param pattern - The pattern with optional wildcards (*)
 *
 * @example
 * matchWildcard("ls -la", "ls*") // true
 * matchWildcard("git diff HEAD", "git diff*") // true
 * matchWildcard("rm -rf /", "*") // true
 */
export function matchWildcard(value: string, pattern: string): boolean {
	if (pattern === "*") return true

	// Escape regex special chars except *
	const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, "\\$&")
	// Convert * to .* for regex matching
	const regex = new RegExp(`^${escaped.replace(/\*/g, ".*")}$`)
	return regex.test(value)
}

/**
 * Check permission for a value against a set of patterns.
 *
 * Patterns are checked from most specific to least specific:
 * 1. Exact matches (no wildcards) first
 * 2. Longer patterns before shorter ones
 * 3. Wildcard-only pattern (*) last
 *
 * @param value - The value to check (command, file path, etc.)
 * @param patterns - Pattern-to-permission mapping
 * @returns The permission level for this value
 *
 * @example
 * checkPermission("ls -la", { "ls*": "allow", "*": "ask" }) // "allow"
 * checkPermission("npm install", { "ls*": "allow", "*": "ask" }) // "ask"
 */
export function checkPermission(
	value: string,
	patterns: Record<string, Permission>,
): Permission {
	// Sort patterns from most specific to least specific
	const sortedPatterns = Object.keys(patterns).sort((a, b) => {
		// Exact matches (no wildcards) come first
		const aHasWildcard = a.includes("*")
		const bHasWildcard = b.includes("*")
		if (!aHasWildcard && bHasWildcard) return -1
		if (aHasWildcard && !bHasWildcard) return 1

		// Wildcard-only pattern comes last
		if (a === "*") return 1
		if (b === "*") return -1

		// Longer patterns are more specific
		return b.length - a.length
	})

	for (const pattern of sortedPatterns) {
		if (matchWildcard(value, pattern)) {
			return patterns[pattern]!
		}
	}

	// Default to ask if no pattern matches
	return "ask"
}

export class PermissionDeniedError extends Error {
	constructor(
		public readonly operation: string,
		public readonly value: string,
	) {
		super(`Permission denied: ${operation} "${value}" is not allowed`)
		this.name = "PermissionDeniedError"
	}
}

import type { LanguageModel, ModelMessage } from "ai"
import { summarizeMessages } from "@/agents/lib/context"

const SUMMARIZE_THRESHOLD = 180_000
const SUMMARIZE_KEEP_RECENT = 8
const SUMMARIZE_PROTECT_TOKENS = 40_000

/**
 * Rough token estimate: ~4 chars per token.
 * Used as a fallback when actual usage data isn't available (e.g. first step).
 */
function estimateMessageTokens(messages: ModelMessage[]): number {
	let chars = 0
	for (const msg of messages) {
		if (typeof msg.content === "string") {
			chars += msg.content.length
		} else if (Array.isArray(msg.content)) {
			for (const part of msg.content) {
				if ("text" in part && typeof part.text === "string") {
					chars += part.text.length
				} else if ("value" in part) {
					chars += JSON.stringify(part.value).length
				} else if ("input" in part) {
					chars += JSON.stringify(part.input).length
				}
				if ("output" in part) {
					chars += JSON.stringify(part.output).length
				}
			}
		}
	}
	return Math.ceil(chars / 4)
}

/**
 * Creates a `prepareStep` handler that automatically summarizes
 * older messages once the conversation exceeds the token threshold.
 *
 * Uses the previous step's actual inputTokens when available,
 * and falls back to a character-based estimate for the first step
 * (where no usage data exists yet).
 */
export function createContextSummarizer(model: LanguageModel) {
	return async ({
		steps,
		messages,
	}: {
		steps: Array<{ usage?: { inputTokens?: number } }>
		messages: ModelMessage[]
	}) => {
		const lastStep = steps.at(-1)
		const inputTokens =
			lastStep?.usage?.inputTokens ?? estimateMessageTokens(messages)

		if (inputTokens < SUMMARIZE_THRESHOLD) {
			return {}
		}

		const summarized = await summarizeMessages(messages, model, {
			threshold: SUMMARIZE_THRESHOLD,
			keepRecent: SUMMARIZE_KEEP_RECENT,
			protectTokens: SUMMARIZE_PROTECT_TOKENS,
		})

		return summarized ? { messages: summarized } : {}
	}
}

/**
 * Stops the agent loop when the last step produced text
 * without making any tool calls (i.e., the agent is done).
 */
export function stopOnTextResponse({
	steps,
}: {
	steps: Array<{ toolCalls?: Array<unknown> }>
}) {
	if (steps.length === 0) return false

	const lastStep = steps[steps.length - 1]
	if (!lastStep) return false

	if (lastStep.toolCalls && lastStep.toolCalls.length > 0) {
		return false
	}

	return true
}
